$:set -euo pipefail
api=repos/BestNameYet/Terminals/contents/workspaces/2d-state-event-procedure-design/src/user_intent.mjs
expected=26cb8a8683daa279ad5d47fa299df58e991c9f3d
content=$(base64 -w0 <<'STEP_SOURCE'
async function captureUserIntent(e, i, read) {
  const keyword = "user_intent"
  const schema = await returnSchema(keyword)

  const state = {
    instruction: await instruction(keyword),
    return_schema: schema,
    context: { verbatim_request: read("verbatim_request") }
  }

  const previousError = e[i]?.error
  if (previousError) {
    state.error_message = previousError
  }

  const input = await render(state)
  return validate(input, schema)
}
STEP_SOURCE
)
commit=$(gh api --method PUT "$api" -f branch=main -f message='Save user_intent step template' -f content="$content" --jq .commit.sha)
test "$(gh api "$api?ref=$commit" --jq .sha)" = "$expected"
test "$(gh api "$api?ref=main" --jq .sha)" = "$expected"
printf 'published_commit=%s\npublished_blob=%s\n' "$commit" "$expected"
